# Generated by tools/render_controls.py — edit the data files, not this file.
#
# Rule:        CKV_AWS_169 (checkov 3.3.16)
# Applies to:  aws_sns_topic_policy
# Read with:   aws_policy_documents — aws_sns_topic_policy → no_wildcard_principal
#              predicate: libraries/_policy_document.rb
#              fetch:     tools/policy_specs.yml
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_169'] || []

control 'CKV_AWS_169' do
  title 'Ensure SNS topic policy is not public by only allowing specific services or principals to access it'

  desc <<~DESC
    Checkov asserts this against the policy document in the Terraform. This
    profile fetches the policy AWS actually has on each aws_sns_topic_policy
    and evaluates the same question over its statements: no Allow statement
    grants a wildcard principal with no Condition.

    Stronger than Checkov: a topic policy is one of the few documents AWS
    itself rewrites — subscribing a queue, or letting a bucket publish
    events, appends a statement that never appears in the Terraform. Reading
    the deployed document is the only way to see what those appended
    statements actually allow.
  DESC

  desc 'rationale', <<~RATIONALE
    An unconditioned wildcard principal on a topic policy lets any AWS
    account, and an anonymous caller, subscribe to the topic or publish to
    it. Subscribing exfiltrates every message the topic will ever carry —
    and topics carry alarms, order events and operational detail that
    describe the system to an attacker. Publishing is worse: it injects
    messages into whatever the subscribers do next.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_sns_topic_policy: the topic policy has no Allow
    statement whose Principal is '*', or whose Principal.AWS contains '*',
    without ANY Condition on the statement (Checkov runs cloudsplaining's
    internet_accessible_actions, which is the same test with a CURATED
    allow-list of restrictive condition keys — so a topic granting '*' under
    a condition that does not actually narrow it, a date or a userAgent
    match, passes here and fails in Checkov)
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_sns_topic_policy:

      resource "aws_sns_topic_policy" "app" {
        arn = aws_sns_topic.app.arn

        policy = jsonencode({
          Version = "2012-10-17"
          Statement = [
            {
              Sid       = "AllowOwnerPublish"
              Effect    = "Allow"
              Principal = { AWS = aws_iam_role.publisher.arn }
              Action    = "SNS:Publish"
              Resource  = aws_sns_topic.app.arn
            },
            {
              Sid       = "AllowServicePublish"
              Effect    = "Allow"
              Principal = { Service = "s3.amazonaws.com" }
              Action    = "SNS:Publish"
              Resource  = aws_sns_topic.app.arn
              Condition = {
                ArnLike      = { "aws:SourceArn" = aws_s3_bucket.app.arn }
                StringEquals = { "aws:SourceAccount" = data.aws_caller_identity.current.account_id }
              }
            },
          ]
        })
      }

    Out of band — aws_sns_topic_policy:

      aws sns set-topic-attributes --topic-arn <topic-arn> --attribute-name Policy --attribute-value file://topic-policy.json

    Note (aws_sns_topic_policy): set-topic-attributes REPLACES the Policy
    attribute, so start from the current one (`aws sns get-topic-attributes
    --topic-arn <arn> --query 'Attributes.Policy' --output text`). Do not delete
    the AWS-written default statement while narrowing the others — it is the one
    that lets the account manage its own topic, and it is already conditioned on
    AWS:SourceOwner so this control does not report it. Where a wildcard
    principal is genuinely needed (an S3 bucket or an SES rule publishing to the
    topic), the fix is the Condition, not the Principal: aws:SourceArn plus
    aws:SourceAccount both scopes the grant and takes the statement out of scope
    here.
  FIX

  tag checkov_id:            'CKV_AWS_169'
  tag checkov_category:      'IAM'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_sns_topic_policy]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/sns_topic_policy'
  tag policy_source:         'aws_sns_topic_policy'
  tag policy_predicate:      'no_wildcard_principal'
  tag nist:                  ['AC-3', 'AC-6']
  tag nist_r4:               ['AC-3', 'AC-6']
  tag cci:                   ['CCI-000213', 'CCI-000225']
  tag ksi:                   ['KSI-IAM-CTL']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_policy_documents(type: 'aws_sns_topic_policy', source: 'aws_sns_topic_policy',
                                predicate: 'no_wildcard_principal', regions: scan_regions)

  # A region — or a whole service — that could not be READ is not the same as
  # one with nothing in it. A denied call or an unreachable endpoint ends up
  # here, and without this assertion it renders as "no assets" and the control
  # reports Not Applicable: the worst case reported as "does not apply here".
  unreadable = assets.unreadable_regions
  unless unreadable.empty?
    describe 'aws_sns_topic_policy enumeration' do
      it 'read every region it attempted' do
        expect(unreadable.map { |r| "#{r[:region]}: #{r[:error]}" }).to be_empty
      end
    end
  end

  # An asset whose policy could not be read or parsed has NO VERDICT. It is not
  # in `assets` below, because a nil offender list compared against [] would
  # pass — a denied GetPolicy silently reporting the least-visible estate as the
  # cleanest one. It fails here instead, naming the asset and the reason.
  #
  # An asset with no policy at all is NOT here: that is a real answer and a
  # passing one, recorded on the row as policy_present: false.
  undecidable = assets.undecidable
  unless undecidable.empty?
    describe 'aws_sns_topic_policy policy documents' do
      it 'could all be read and parsed' do
        expect(undecidable).to be_empty
      end
    end
  end

  in_scope = assets.assets(exempt: exempt)

  # Both failure lists keep the control APPLICABLE. only_if suppresses the whole
  # control, including the two assertions above, so a guard that skips when the
  # enumeration broke is no guard at all: it would suppress exactly the case it
  # exists to catch.
  applicable = !in_scope.empty? || !undecidable.empty? || !unreadable.empty?

  # Two statements, not a ternary: InSpec's AST impact collector calls `.value`
  # on the argument node, and a ternary is an IfNode with none — it aborts
  # `check` for the whole profile before a single control runs.
  impact 0.7
  impact 0.0 unless applicable

  only_if('no aws_sns_topic_policy in scope') { applicable }

  in_scope.each do |asset|
    describe "aws_sns_topic_policy #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      it 'no Allow statement grants a wildcard principal with no Condition' do
        expect(asset[:offenders]).to eq([]),
          "#{asset[:offenders].length} offending statement(s) — " \
          "#{asset[:offenders].join(' | ')}"
      end
    end
  end
end
